import sqlite3

def decorator(func):
    def wrapper(*args, **kwargs):
        conn = sqlite3.connect(filename)
        c = conn.cursor()
        c.execute(
            """CREATE TABLE IF NOT EXISTS {func_name} (args text, kwargs text, result text)""".format(
                func_name=func_name
            )
        )
        c.execute(
            """SELECT * FROM {func_name} WHERE args = ? AND kwargs = ?""".format(
                func_name=func_name
            ),
            (str(args), str(kwargs)),
        )
        result = c.fetchone()
        if result is None:
            result = func(*args, **kwargs)
            c.execute(
                """INSERT INTO {func_name} (args, kwargs, result) VALUES (?, ?, ?)""".format(
                    func_name=func_name
                ),
                (str(args), str(kwargs), str(result)),
            )
            conn.commit()
        else:
            result = result[2]
        conn.close()
        return result

    return wrapper

return decorator

