import jieba
import nltk

def tokenize(text):
    return list(jieba.tokenize(text))

def get_tokens(text):
    return [tok.text for tok in tokenize(text)]

def get_ngrams(n, text):
    ngram = dict()
    tokens = get_tokens(text)
    for i in range(len(tokens) - n + 1):
        if tokens[i:i + n] in ngram:
            ngram[tokens[i:i + n]] += 1
        else:
            ngram[tokens[i:i + n]] = 1
    return ngram

def get_ngram_overlap(ngram_continuation, ngram_reference):
    overlap = 0
    for ngram in ngram_continuation:
        if ngram in ngram_reference:
            overlap += min(ngram_continuation[ngram], ngram_reference[ngram])
    return overlap

def rouge_n(continuation, reference, n=2):
    ngram_continuation = get_ngrams(n, continuation)
    ngram_reference = get_ngrams(n, reference)
    ngram_overlap = get_ngram_overlap(ngram_continuation, ngram_reference)
    return ngram_overlap / len(ngram_reference)

def rouge_l_sentence_level(continuation, reference):
    tokens_continuation = get_tokens(continuation)
    tokens_reference = get_tokens(reference)
    length_reference = len(tokens_reference)
    if length_reference == 0:
        return 0
    length_lcs = nltk.translate.bleu_score.sentence_bleu(
        [tokens_reference],
        tokens_continuation,
        smoothing_function=nltk.translate.bleu_score.SmoothingFunction().method1
    )
    return length_lcs / length_reference

def rouge_l(continuation, reference):
    return rouge_l_sentence_level(continuation, reference)

return rouge_l(continuation, reference)

