def locate_object(name: str) -> Any:

    """
    Locates and returns a Python object based on its fully qualified name given as a string. An exception is raised if the object cannot be located.

    Input-Output Arguments
    :param name: str, The fully qualified name of the object to locate, in the format "module.submodule.class_name".
    :return: Any. The located Python object.
    """

    try:
        module_name, class_name = name.rsplit(".", 1)
        module = importlib.import_module(module_name)
        return getattr(module, class_name)
    except (AttributeError, ImportError) as e:
        raise ValueError(f"Unable to locate object '{name}'.") from e

