def _pack_greedily(items, weights=None, num_bins=None, file_size=False):
    if weights is None:
        weights = [1] * len(items)

    if num_bins is None:
        num_bins = len(items)

    bins = [[] for _ in range(num_bins)]
    bin_weights = [0] * num_bins

    for i, item in enumerate(items):
        best_bin = None
        best_weight = None

        for j, bin_weight in enumerate(bin_weights):
            if best_bin is None or bin_weight + weights[i] < best_weight:
                best_bin = j
                best_weight = bin_weight + weights[i]

        bins[best_bin].append(item)
        bin_weights[best_bin] += weights[i]

    for i, bin in enumerate(bins):
        random.shuffle(bin)

    if file_size:
        print("File sizes per worker:")
        for i, bin in enumerate(bins):
            print(f"Worker {i}: {sum(weights[j] for j in bin) / 1e6:.2f} MB")
    else:
        print("Weights per worker:")
        for i, bin in enumerate(bins):
            print(f"Worker {i}: {sum(weights[j] for j in bin)}")

    return bins

