    items_per_worker = len(user_items) // total_workers
else:
    items_per_worker = len(user_items) // total_workers + 1

items_per_worker_list = [items_per_worker] * total_workers

if len(user_items) % total_workers != 0:
    for i in range(len(user_items) % total_workers):
        items_per_worker_list[total_workers - i - 1] -= 1

items_per_worker_list = np.cumsum(items_per_worker_list)

if node_rank == 0:
    start_idx = 0
else:
    start_idx = items_per_worker_list[node_rank - 1]

end_idx = items_per_worker_list[node_rank]

items_for_node = user_items[start_idx:end_idx]

return items_for_node

