def get_flops(module: nn.Module):
    def get_flops_func(module: nn.Module, input: torch.Tensor, output: torch.Tensor):
        flops = 0
        if isinstance(module, torch.nn.Conv2d):
            flops += (
                module.weight.shape[0]
                * module.weight.shape[1]
                * module.weight.shape[2]
                * module.weight.shape[3]
                * output.shape[2]
                * output.shape[3]
            )
            flops += output.numel()
        elif isinstance(module, torch.nn.BatchNorm2d):
            flops += output.numel() * 2
        elif isinstance(module, torch.nn.ReLU):
            flops += output.numel()
        elif isinstance(module, torch.nn.MaxPool2d):
            flops += output.numel()
        elif isinstance(module, torch.nn.AvgPool2d):
            flops += output.numel()
        elif isinstance(module, torch.nn.Linear):
            flops += output.numel() * (module.weight.shape[0] + module.weight.shape[1])
        return flops

    return get_flops_func

