from torch import nn
from torch.jit import trace
from functools import partial

def aot_forward(fn):

    """
    The function checks if the input argument is an instance of a PyTorch neural network module. If it is, it compiles the module using a forward compiler specific for modules. If the input is not a module, it assumes it's a function and compiles it using a forward compiler specific for functions.

    Input-Output Arguments
    :param fn: torch.nn.Module or function. The neural network module or function to be compiled.
    :return: The compiled module or function using the specified forward compiler.
    """

    if isinstance(fn, nn.Module):
        return trace(fn, torch.rand(1, 3, 224, 224))
    else:
        return trace(fn, torch.rand(1, 3, 224, 224))

def aot_backward(fn):

    """
    The function checks if the input argument is an instance of a PyTorch neural network module. If it is, it compiles the module using a backward compiler specific for modules. If the input is not a module, it assumes it's a function and compiles it using a backward compiler specific for functions.

    Input-Output Arguments
    :param fn: torch.nn.Module or function. The neural network module or function to be compiled.
    :return: The compiled module or function using the specified backward compiler.
    """

    if isinstance(fn, nn.Module):
        return torch.jit.trace_module(fn, dict(forward_fn=partial(aot_forward, fn)))
    else:
        return torch.jit.trace_module(fn, dict(forward_fn=partial(aot_forward, fn)))

return aot_forward(fn), aot_backward(fn)

