def normalize(v):
  return v / la.norm(v)

def is_symmetric(v1, v2, eps=1e-4):
  return abs(np.dot(v1, v2)) > 1 - eps

def remove_symmetric_vertices(vertices, eps=1e-4):
  unique_vertices = []
  for v in vertices:
    is_unique = True
    for u in unique_vertices:
      if is_symmetric(v, u, eps):
        is_unique = False
        break
    if is_unique:
      unique_vertices.append(v)
  return unique_vertices

